"""Report and case export service supporting JSON and CSV formats with formula-injection neutralization."""

import csv
import io
import json
from datetime import UTC, datetime
from typing import Any

from app.schemas.cases import CaseDetailResponse
from app.schemas.threat_report import ThreatReport

DISCLAIMER_TEXT = (
    "DISCLAIMER: This threat assessment was generated by CIPHER AI using deterministic security heuristics "
    "and bounded AI telemetry. Assessments represent observed indicators at the time of scanning and do not "
    "guarantee complete safety. Malicious threats may evolve or evade detection."
)

FORMULA_PREFIXES = ("=", "+", "-", "@", "\t", "\r")


def neutralize_csv_cell(val: Any) -> str:
    """Prepend single quote to neutralize spreadsheet formula execution."""
    if val is None:
        return ""
    text = str(val)
    if text and (text.startswith(FORMULA_PREFIXES) or text.strip().startswith(FORMULA_PREFIXES)):
        return f"'{text}"
    return text


class ExportService:
    @classmethod
    def export_scan(cls, report: ThreatReport, format: str = "json") -> tuple[bytes, str]:
        """Convenience method returning raw bytes and content-type."""
        if format.lower() == "csv":
            return cls.export_scan_csv(report).encode("utf-8"), "text/csv; charset=utf-8"
        return cls.export_scan_json(report).encode("utf-8"), "application/json"

    @classmethod
    def export_case(cls, case: CaseDetailResponse, format: str = "json") -> tuple[bytes, str]:
        """Convenience method returning raw bytes and content-type for a case."""
        if format.lower() == "csv":
            return cls.export_case_csv(case).encode("utf-8"), "text/csv; charset=utf-8"
        return cls.export_case_json(case).encode("utf-8"), "application/json"

    @staticmethod
    def export_scan_json(report: ThreatReport) -> str:
        """Export full scan threat report with metadata and disclaimer as JSON."""
        data = report.model_dump(mode="json")
        data["export_metadata"] = {
            "exported_at": datetime.now(UTC).isoformat(),
            "export_version": "1.0",
            "disclaimer": DISCLAIMER_TEXT,
        }
        return json.dumps(data, indent=2)

    @staticmethod
    def export_scan_csv(report: ThreatReport) -> str:
        """Export scan evidence and indicators as a sanitized CSV table."""
        output = io.StringIO()
        writer = csv.writer(output, quoting=csv.QUOTE_MINIMAL)

        # Header row
        writer.writerow(
            [
                "Scan ID",
                "Target",
                "Scan Type",
                "Risk Score",
                "Risk Level",
                "Indicator ID",
                "Category",
                "Severity",
                "Indicator Title",
                "Score Points",
                "Triggered",
                "Description / Reason",
            ]
        )

        scan_id = report.scan_id or report.report_id
        target = report.input.display_value
        scan_type = (
            report.scan_type.value if hasattr(report.scan_type, "value") else str(report.scan_type)
        )
        score = report.assessment.risk_score
        level = (
            report.assessment.risk_level.value
            if hasattr(report.assessment.risk_level, "value")
            else str(report.assessment.risk_level)
        )

        score_by_id = {sc.indicator_id: sc.points for sc in report.score_breakdown}

        for ind in report.indicators:
            cat = ind.category.value if hasattr(ind.category, "value") else str(ind.category)
            sev = ind.severity.value if hasattr(ind.severity, "value") else str(ind.severity)
            pts = score_by_id.get(ind.indicator_id, 0)

            writer.writerow(
                [
                    neutralize_csv_cell(scan_id),
                    neutralize_csv_cell(target),
                    neutralize_csv_cell(scan_type),
                    neutralize_csv_cell(score),
                    neutralize_csv_cell(level),
                    neutralize_csv_cell(ind.indicator_id),
                    neutralize_csv_cell(cat),
                    neutralize_csv_cell(sev),
                    neutralize_csv_cell(ind.title),
                    neutralize_csv_cell(pts),
                    neutralize_csv_cell("Yes" if ind.triggered else "No"),
                    neutralize_csv_cell(ind.description),
                ]
            )

        return output.getvalue()

    @staticmethod
    def export_case_json(case_detail: CaseDetailResponse) -> str:
        """Export entire investigation case dossier with timeline as JSON."""
        data = case_detail.model_dump(mode="json")
        data["export_metadata"] = {
            "exported_at": datetime.now(UTC).isoformat(),
            "export_version": "1.0",
            "disclaimer": DISCLAIMER_TEXT,
        }
        return json.dumps(data, indent=2)

    @staticmethod
    def export_case_csv(case_detail: CaseDetailResponse, include_notes: bool = True) -> str:
        """Export case scans and timeline notes into a sanitized CSV."""
        output = io.StringIO()
        writer = csv.writer(output, quoting=csv.QUOTE_MINIMAL)

        writer.writerow(
            [
                "Record Type",
                "Case ID",
                "Case Title",
                "Status",
                "Priority",
                "Item ID",
                "Details / Content",
                "Risk Level",
                "Date",
            ]
        )

        cid = case_detail.id
        ctitle = case_detail.title
        cstatus = case_detail.status
        cpriority = case_detail.priority

        # Write scans
        for s in case_detail.scans:
            writer.writerow(
                [
                    "Attached Scan",
                    neutralize_csv_cell(cid),
                    neutralize_csv_cell(ctitle),
                    neutralize_csv_cell(cstatus),
                    neutralize_csv_cell(cpriority),
                    neutralize_csv_cell(s.id),
                    neutralize_csv_cell(s.title or s.input_preview),
                    neutralize_csv_cell(s.risk_level),
                    neutralize_csv_cell(s.created_at),
                ]
            )

        # Write notes if requested
        if include_notes:
            for n in case_detail.notes:
                writer.writerow(
                    [
                        "Analyst Note",
                        neutralize_csv_cell(cid),
                        neutralize_csv_cell(ctitle),
                        neutralize_csv_cell(cstatus),
                        neutralize_csv_cell(cpriority),
                        neutralize_csv_cell(n.id),
                        neutralize_csv_cell(n.body),
                        neutralize_csv_cell("N/A"),
                        neutralize_csv_cell(n.created_at),
                    ]
                )

        return output.getvalue()


_export_service = ExportService()


def get_export_service() -> ExportService:
    return _export_service
